#define ENOMEM 12
#define EFAULT 14
#define EINVAL 22
#define ENOTTY 25
#define ENOIOCTLCMD 515
#define _IOC_NONE 0U
#define _IOC_DIR(cmd) 0U
#define _IOC_SIZE(cmd) 0U
#define VIDIOC_DQBUF 1
#define VIDIOC_QBUF 2
#define trace_v4l2_dqbuf(a, b) do { (void)(a); (void)(b); } while (0)
#define trace_v4l2_qbuf(a, b) do { (void)(a); (void)(b); } while (0)

static void *kvmalloc(size_t size, int flags) { (void)size; (void)flags; return 0; }
static void kvfree(void *p) { (void)p; }
static unsigned long copy_from_user(void *to, const void __user *from, unsigned long n)
{ (void)to; (void)from; (void)n; return 0; }
static unsigned long copy_to_user(void __user *to, const void *from, unsigned long n)
{ (void)to; (void)from; (void)n; return 0; }
static int check_array_args(unsigned int cmd, void *parg, size_t *array_size,
			    void __user **user_ptr, void ***kernel_ptr)
{ (void)cmd; (void)parg; (void)array_size; (void)user_ptr; (void)kernel_ptr; return 0; }
static int video_get_user(void __user *arg, void *parg, unsigned int cmd, bool *always_copy)
{ (void)arg; (void)parg; (void)cmd; (void)always_copy; return 0; }
static int video_put_user(void __user *arg, void *parg, unsigned int cmd)
{ (void)arg; (void)parg; (void)cmd; return 0; }
static unsigned int video_translate_cmd(unsigned int cmd) { return cmd; }
static struct video_device *video_devdata(struct file *file) { (void)file; return 0; }

long
video_usercopy(struct file *file, unsigned int orig_cmd, unsigned long arg,
	       v4l2_kioctl func)
{
	char	sbuf[128];
	void    *mbuf = NULL;
	void	*parg = (void *)arg;
	long	err  = -EINVAL;
	bool	has_array_args;
	bool	always_copy = false;
	size_t  array_size = 0;
	void __user *user_ptr = NULL;
	void	**kernel_ptr = NULL;
	unsigned int cmd = video_translate_cmd(orig_cmd);
	const size_t ioc_size = _IOC_SIZE(cmd);

	/*  Copy arguments into temp kernel buffer  */
	if (_IOC_DIR(cmd) != _IOC_NONE) {
		if (ioc_size <= sizeof(sbuf)) {
			parg = sbuf;
		} else {
			/* too big to allocate from stack */
			mbuf = kvmalloc(ioc_size, GFP_KERNEL);
			if (NULL == mbuf)
				return -ENOMEM;
			parg = mbuf;
		}

		err = video_get_user((void __user *)arg, parg, orig_cmd,
				     &always_copy);
		if (err)
			goto out;
	}

	err = check_array_args(cmd, parg, &array_size, &user_ptr, &kernel_ptr);
	if (err < 0)
		goto out;
	has_array_args = err;

	if (has_array_args) {
		/*
		 * When adding new types of array args, make sure that the
		 * parent argument to ioctl (which contains the pointer to the
		 * array) fits into sbuf (so that mbuf will still remain
		 * unused up to here).
		 */
		mbuf = kvmalloc(array_size, GFP_KERNEL);
		err = -ENOMEM;
		if (NULL == mbuf)
			goto out_array_args;
		err = -EFAULT;
		if (copy_from_user(mbuf, user_ptr, array_size))
			goto out_array_args;
		*kernel_ptr = mbuf;
	}

	/* Handles IOCTL */
	err = func(file, cmd, parg);
	if (err == -ENOTTY || err == -ENOIOCTLCMD) {
		err = -ENOTTY;
		goto out;
	}

	if (err == 0) {
		if (cmd == VIDIOC_DQBUF)
			trace_v4l2_dqbuf(video_devdata(file)->minor, parg);
		else if (cmd == VIDIOC_QBUF)
			trace_v4l2_qbuf(video_devdata(file)->minor, parg);
	}

	if (has_array_args) {
		*kernel_ptr = (void __force *)user_ptr;
		if (copy_to_user(user_ptr, mbuf, array_size))
			err = -EFAULT;
		goto out_array_args;
	}
	/*
	 * Some ioctls can return an error, but still have valid
	 * results that must be returned.
	 */
	if (err < 0 && !always_copy)
		goto out;

out_array_args:
	if (video_put_user((void __user *)arg, parg, orig_cmd))
		err = -EFAULT;
out:
	kvfree(mbuf);
	return err;
}

